#!/usr/bin/env node
// sync-brand.mjs — brand files served or bundled by the Hub are copies of an origin folder.
// The origin is hub-brand/: the Companion Hub's own mark and icons, owned by this repo and
// generated by hub-brand/scripts (see hub-brand/README.md). Everything that says "this app".
//
// The Companion Intelligence company logo (brand/, vendored from CI Common, listed in
// ci-common.vendor.json) is not mirrored: nothing the Hub serves or bundles is the company mark.
// Add a company-identity surface (attribution, an About page) and its copy back here.
//
// A static export needs the copies on disk, so they are committed; this script is what
// makes them a mirror rather than a second hand-maintained original.
//
//   node scripts/sync-brand.mjs            # rewrite every copy from its origin
//   node scripts/sync-brand.mjs --check    # exit 1 if any copy differs from its origin
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..'); // packages/frontend
const argv = process.argv.slice(2);
const CHECK = argv.includes('--check');
const HUB_ORIGIN = resolve(dirname(fileURLToPath(import.meta.url)), '../hub-brand');

/** Hub copy → origin path (relative to packages/frontend/hub-brand). Dest is relative to packages/frontend. */
const HUB_MAP = {
  'public/logo.svg': 'logos/mark-small.svg', // header icon (32 px) and QR centre: under 48 px, so the small mark
  'public/hub-mark.svg': 'logos/mark.svg', // the full mark where it is shown large: the mobile connect screen
  'public/hub.png': 'icons/png/mark-512.png', // getLogo()
  'public/hub-christmas.png': 'icons/png/mark-512.png', // getLogo() seasonal slot; the old file was the plain mark too
  'public/icons/favicon.svg': 'logos/mark-small.svg',
  'public/icons/favicon.ico': 'icons/png/favicon.ico',
  'public/icons/favicon-96x96.png': 'icons/png/favicon-96.png',
  'public/icons/apple-touch-icon.png': 'icons/png/apple-touch-icon-180.png',
  'public/icons/web-app-manifest-192x192.png': 'icons/png/icon-192.png',
  'public/icons/web-app-manifest-512x512.png': 'icons/png/icon-512.png',
  // The setup page and the bootstrap page show this at 48 and 30 px, so it is the small mark.
  'src/assets/hub-logo.png': 'icons/png/mark-small-160.png', // inlined by SetupPageShell
  '../desktop/bootstrap/assets/hub-logo.png': 'icons/png/mark-small-160.png', // the bootstrap page ships the same file
  '../desktop/bootstrap/assets/hub-icon.png': 'icons/png/mark-40.png',
  '../desktop/src-tauri/icons/tray.png': 'icons/png/tray-64.png', // loaded by tray.rs
  // Unreferenced by Tauri, but it used to hold an earlier mark. Keep it the Hub mark so it cannot go stale again.
  '../desktop/src-tauri/icons/icon.svg': 'logos/mark-tight.svg',
  '../mobile/src-tauri/icons/icon.svg': 'logos/mark-tight.svg',
};

const ENTRIES = Object.entries(HUB_MAP).map(([dest, src]) => [dest, src, HUB_ORIGIN]);

const sha = (b) => createHash('sha256').update(b).digest('hex');
const drift = [];
let n = 0;
for (const [dest, src, origin] of ENTRIES) {
  const from = join(origin, src);
  const to = join(ROOT, dest);
  if (!existsSync(from)) {
    drift.push(`${src}: missing in origin ${origin}`);
    continue;
  }
  const bytes = readFileSync(from);
  const same = existsSync(to) && sha(readFileSync(to)) === sha(bytes);
  if (same) {
    n++;
    continue;
  }
  if (CHECK) drift.push(`${dest} differs from ${src}`);
  else {
    mkdirSync(dirname(to), { recursive: true });
    writeFileSync(to, bytes);
    console.log(`  wrote ${dest} ← ${src}`);
    n++;
  }
}
if (drift.length) {
  console.error(`✖ brand assets:\n  ${drift.join('\n  ')}\n  run \`node scripts/sync-brand.mjs\``);
  process.exit(1);
}
console.log(`✔ ${n} brand file(s) match their origin (${HUB_ORIGIN})`);
